        options.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        options.setFeature("http://xml.org/sax/features/external-general-entities", false);
        options.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        // Parse the input stream with the secure options
        Document<T> document = parser.parse(entityStream, options);

        // Return the root element of the parsed Atom document
        return document.getRoot();
    }

    // other methods
}
