import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        if (name.isEmpty()) {
            throw new IllegalArgumentException("File name must not be empty");
        }

        // Resolve the requested file against the target directory
        File file = new File(dir, name);

        // Normalise paths and ensure the resulting file stays within the target directory
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path filePath = file.toPath().toAbsolutePath().normalize();

        if (!filePath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                    "Attempt to create file outside of target directory: " + name);
        }

        // Split the name into prefix and suffix for collision handling
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);

        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
            filePath = file.toPath().toAbsolutePath().normalize();
            if (!filePath.startsWith(dirPath)) {
                throw new IllegalArgumentException(
                        "Generated filename escapes target directory: " + file.getName());
            }
        }

        // Create parent directories if necessary
        File parent = file.getParentFile();
        if (parent != null && !parent.exists() && !parent.mkdirs() && !parent.isDirectory()) {
            throw new IllegalStateException("Unable to create parent directories for " + file);
        }

        return file;
    }

    // other methods

}
