            return null;
        }

        // Skip all leading slashes
        int i = 0;
        while (i < path.length() && path.charAt(i) == '/') {
            i++;
        }

        // Remaining part after removing leading slashes
        final String remaining = path.substring(i);

        // If nothing remains, the path was all slashes – return a single '/'
        if (remaining.isEmpty()) {
            return "/";
        }

        // Prepend a single slash to the remaining part
        return "/" + remaining;
    }

