public class DefaultURLConstructor implements URLConstructor {

    // Regular expression that allows only alphanumeric characters, underscores, hyphens, dots and slashes.
    private static final Pattern SAFE_PATH_PATTERN = Pattern.compile("[A-Za-z0-9_\\-./]+");

    // Default page to forward to when the requested path is unsafe or missing.
    private static final String DEFAULT_PAGE = "Wiki.jsp";

    // other methods

    /**
     * Returns a sanitized page name derived from the request's path info.
     * <p>
     * The method performs the following checks:
     * <ul>
     *   <li>Null or empty path info results in the default page.</li>
     *   <li>Leading slashes are removed to avoid absolute paths.</li>
     *   <li>Any occurrence of {@code ".."} or backslashes is rejected.</li>
     *   <li>The remaining string must match {@link #SAFE_PATH_PATTERN}.</li>
     *   <li>Paths starting with a dot or containing {@code "/."} are rejected.</li>
     * </ul>
     * If all checks pass, the trimmed path is returned; otherwise the default page is returned.
     *
     * @param request the HTTP request that led to this page
     * @return a safe page name, or {@value #DEFAULT_PAGE} if the input is unsafe
     */
    @Override
    public String getForwardPage(HttpServletRequest request) {
        String pathInfo = request.getPathInfo();

        // 1. Handle null or empty path info
        if (pathInfo == null || pathInfo.isEmpty()) {
            return DEFAULT_PAGE;
        }

        // 2. Strip a leading slash to work with a relative path
        String trimmed = pathInfo.startsWith("/") ? pathInfo.substring(1) : pathInfo;

        // 3. Reject obvious traversal attempts
        if (trimmed.contains("..") || trimmed.contains("\\") || trimmed.contains("//")) {
            return DEFAULT_PAGE;
        }

        // 4. Enforce allowed character set
        if (!SAFE_PATH_PATTERN.matcher(trimmed).matches()) {
            return DEFAULT_PAGE;
        }

        // 5. Reject hidden or relative segments
        if (trimmed.startsWith(".") || trimmed.contains("/.")) {
            return DEFAULT_PAGE;
        }

        // 6. All checks passed – return the sanitized path
        return trimmed;
    }

