     * @param targetDirectory the root directory where entries will be extracted
     * @throws IOException if an I/O error occurs or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical (real) path of the target directory once.
        Path targetPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Reject empty or null entry names early.
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("archive entry has an empty name");
            }

            // Reject absolute paths – they could escape the target directory.
            Path entryPath = Paths.get(entryName);
            if (entryPath.isAbsolute()) {
                throw new IOException("absolute entry name not allowed: " + entryName);
            }

            // Resolve the entry against the target directory and normalize to eliminate
            // any ".." or "." components. This guarantees that the resulting path is
            // the actual location where the file will be written.
            Path resolvedPath = targetPath.resolve(entryPath).normalize();

            // Verify that the resolved path is still within the target directory.
            if (!resolvedPath.startsWith(targetPath)) {
                throw new IOException(
                        "expanding " + entryName + " would create file outside of "
                                + targetDirectory.getAbsolutePath());
            }

            File outFile = resolvedPath.toFile();

            if (nextEntry.isDirectory()) {
                // Ensure the directory exists.
                if (!outFile.isDirectory() && !outFile.mkdirs()) {
                    throw new IOException("failed to create directory " + outFile);
                }
            } else {
                // Ensure parent directories exist.
                File parent = outFile.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("failed to create directory " + parent);
                }

                // Write the entry data atomically.
                try (OutputStream out = Files.newOutputStream(
                        resolvedPath, StandardOpenOption.CREATE_NEW,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

